using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class ParkingPlazaVerify{static ParkingPlazaVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("ParkingPlazaVerify.request"))return;File.Delete("ParkingPlazaVerify.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Parking Plaza Atlas Branding and Lighting");var controller=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=controller.IsNight;var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);try{controller.ApplyNight();capture.Invoke(null,new object[]{scene,new Vector3(635,43,-280),new Vector3(704,38,-325),"Parking-Plaza-Final-Night"});}finally{if(night)controller.ApplyNight();else controller.ApplyDay();}var materials=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().ToArray();File.WriteAllText("FinalEnvironmentRoadReview/ParkingPlazaVerified.txt","SUCCESS materials="+materials.Length+" shared existing parking material="+materials[0].name+"; runtime lights="+root.GetComponentsInChildren<Light>(true).Length+"; LOD groups="+root.GetComponentsInChildren<LODGroup>(true).Length+"; sign assets total triangles across both LODs="+root.GetComponentsInChildren<MeshFilter>(true).Sum(f=>f.sharedMesh.triangles.Length/3)+"; shader error="+materials.Any(m=>ShaderUtil.ShaderHasError(m.shader)));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/ParkingPlazaVerified.txt",e.ToString());}}}
